const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const out = path.join(root, 'dist');
// Version asset URLs so a deployment never mixes cached styles with new markup.
const assetVersion=createHash('sha256').update(fs.readdirSync(path.join(root,'src')).sort().map(name=>fs.readFileSync(path.join(root,'src',name))).join('')).digest('hex').slice(0,12);
const siteOrigin = (process.env.PUBLIC_ORIGIN || config.origin).replace(/\/$/, '');
const productionOrigin = config.origin.replace(/\/$/, '');
const isProductionOrigin = siteOrigin === productionOrigin;
const launchReady = publicLaunchReady(config, siteOrigin);
const esc = (s = '') => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
