const demos = [
  {id:'services-professionnels', title:'Le dossier client, du premier message au démarrage', industry:'Services professionnels', short:'Un client transmet sa demande. L’équipe voit les pièces attendues, le responsable et la prochaine action.', prompt:'Une nouvelle demande arrive pour une mission de conseil. Il manque encore deux informations avant de commencer.', visual:'sector-services.svg', action:'Ajouter une demande', seed:['Demande reçue','Dossier à compléter','Prêt pour revue'], steps:['Demande reçue','Informations demandées','Dossier complet','Prêt pour le travail']},
  {id:'batiment-interventions', title:'Une intervention sans versions contradictoires', industry:'Bâtiment & interventions', short:'Planifiez une visite, faites progresser le dossier et gardez les changements visibles pour l’équipe.', prompt:'Une entreprise reçoit une demande d’intervention. Une visite doit être planifiée avant le devis.', visual:'sector-construction.svg', action:'Créer une intervention', seed:['Demande enregistrée','Visite à organiser','Devis en attente'], steps:['Demande reçue','Visite planifiée','Devis à valider','Intervention prête']},
  {id:'commerce-operations', title:'La commande au-delà du bouton « payer »', industry:'Commerce & opérations', short:'Suivez une commande fictive de la réception à la préparation, avec un incident de stock à résoudre.', prompt:'Une commande contient un article indisponible. Le service client doit voir l’exception avant de promettre une date.', visual:'sector-commerce.svg', action:'Créer une commande', seed:['Commande reçue','Stock à vérifier','Préparation bloquée'], steps:['Commande reçue','Stock vérifié','Exception résolue','Prête à expédier']},
  {id:'education', title:'Un dossier de candidature lisible pour tous', industry:'Éducation', short:'Soumettez une candidature fictive et faites avancer la liste de documents et la revue administrative.', prompt:'Une famille a envoyé sa demande, mais une pièce reste manquante. Elle doit savoir ce qui a été reçu.', visual:'sector-education.svg', action:'Créer une candidature', seed:['Candidature reçue','Pièce manquante','Revue administrative'], steps:['Demande reçue','Pièce demandée','Dossier complet','Revue terminée']},
  {id:'sante-administrative', title:'Un rendez-vous confirmé, une équipe préparée', industry:'Santé administrative', short:'Coordonnez une demande de rendez-vous et les étapes d’accueil avec des données entièrement fictives.', prompt:'Une personne demande un rendez-vous. L’équipe doit confirmer un créneau et préparer l’accueil administratif.', visual:'sector-health.svg', action:'Demander un rendez-vous', seed:['Demande reçue','Créneau à confirmer','Accueil à préparer'], steps:['Demande reçue','Créneau proposé','Rendez-vous confirmé','Accueil prêt']}
];
const insights = [
  {id:'quand-un-tableur-devient-un-systeme',title:'Quand un tableur devient le système central de l’entreprise', tag:'Organisation', lead:'Le tableur est souvent le meilleur point de départ. La question apparaît quand plusieurs personnes doivent décider à partir de versions différentes.', paragraphs:['Un fichier partagé permet de démarrer rapidement. On y classe les demandes, les dates et les responsables. Puis l’activité grandit : une personne ajoute une colonne, une autre conserve sa copie, et un changement de statut n’arrive pas jusqu’au client.','Le problème n’est pas le tableur lui-même. Il apparaît quand les règles de travail existent uniquement dans la tête des personnes qui le maintiennent. Qui peut modifier une ligne ? Quel état déclenche une action ? Que faire lorsqu’une information manque ?','Avant de remplacer cet outil, il faut observer les décisions qui l’entourent. Une première application utile peut être très simple : un dossier unique, quelques statuts explicites, un responsable, un historique et une liste des exceptions. Le gain à rechercher est une meilleure compréhension du travail, pas le nombre d’écrans créés.','Une bonne transition conserve ce qui fonctionne déjà. Les données peuvent être importées progressivement, les rôles testés avec l’équipe et les anciennes habitudes comparées au nouveau parcours. C’est ainsi qu’un système devient utilisable au quotidien.']},
  {id:'automatiser-sans-perdre-le-controle',title:'Automatiser sans perdre de vue les exceptions', tag:'Automatisation', lead:'Une action automatisée est facile à montrer. Sa fiabilité se mesure quand quelque chose ne se passe pas comme prévu.', paragraphs:['Envoyer une notification après un formulaire peut faire gagner du temps. Mais si le formulaire est incomplet, que l’adresse est erronée ou que le service destinataire ne répond pas, qui sait que le travail s’est arrêté ?','Un processus automatisé utile a besoin d’états compréhensibles. Il montre ce qui a été reçu, ce qui a été tenté, ce qui a réussi et ce qui attend une décision. Il prévoit aussi une façon de reprendre le traitement sans recommencer à zéro.','Avant d’automatiser, dessinons le trajet de l’information et les décisions humaines nécessaires. Ensuite, nous pouvons automatiser les transmissions répétitives et laisser visibles les cas atypiques. Cela évite de déplacer silencieusement le problème d’une boîte mail vers un autre outil.','Le bon indicateur n’est pas seulement le nombre de clics supprimés. C’est la capacité de l’équipe à répondre rapidement : où en est ce dossier, que manque-t-il et qui peut agir maintenant ?']},
  {id:'un-site-qui-continue-apres-le-formulaire',title:'Un site utile continue après le formulaire', tag:'Expérience client', lead:'Pour le client, « demande envoyée » n’est souvent que le début du parcours.', paragraphs:['Une interface peut être magnifique et pourtant laisser une personne dans l’incertitude après avoir cliqué sur « envoyer ». Le message est-il arrivé ? Quel délai attendre ? Faut-il fournir autre chose ?','Du côté de l’entreprise, la demande peut passer par plusieurs personnes et outils. Si personne ne possède la prochaine action, une relance devient nécessaire. Le site et les opérations ne devraient pas être conçus comme deux mondes séparés.','Un parcours complet relie la confirmation immédiate, l’attribution interne, les informations manquantes et la réponse finale. Selon la situation, cela peut demander un simple suivi de demandes ou un véritable espace client. Le niveau de système doit correspondre au volume et aux enjeux.','La première amélioration est souvent modeste : montrer un état fiable et nommer la prochaine étape. Cela peut transformer une expérience d’attente en une relation plus claire.']}
];

