function write(route, page) { const dir = path.join(out,route); fs.mkdirSync(dir,{recursive:true}); fs.writeFileSync(path.join(dir,'index.html'),shell({...applyPhotography(route,refineTrustContent(route,extendOperationalSEO(route,enrichPage(route,page)))),route}).replace(/((?:href|src)="[^"]+\.(?:css|js))"/g,`$1?v=${assetVersion}"`).replace(/(src="[^"]+assets\/[^"]+)\.png/g,'$1.webp').replace(/(src="assets\/[^"]+)\.png/g,'$1.webp')); }
