const sectionHead=(index,kicker,title,copy='')=>`<div class="section-head"><span class="section-index">${index}</span><div><span class="eyebrow">${kicker}</span><h2>${title}</h2>${copy?`<p>${copy}</p>`:''}</div></div>`;
const serviceCard=(x,base='')=>`<a class="service-card reveal" href="${base}expertises/${x.id}/"><span class="eyebrow">${x.eyebrow}</span><h3>${x.title}</h3><p>${x.summary}</p><span class="card-link">Explorer cette expertise ${arrow}</span></a>`;
const demoCard=(x,base='')=>`<a class="demo-card reveal" href="${base}demonstrations/${x.id}/"><div class="demo-card-art"><img src="${base}assets/${x.visual}" alt="Illustration du parcours ${x.industry.toLowerCase()}" loading="lazy"><span class="demo-card-pill">Données fictives · interactif</span></div><div class="demo-card-info"><span class="eyebrow">${x.industry}</span><h3>${x.title}</h3><p>${x.short}</p><span class="card-link">Essayer le scénario ${arrow}</span></div></a>`;
const hero=(eyebrow,title,description,art)=>
  `<section class="subhero dr-subhero"><div class="subhero-copy"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div><div class="subhero-art dr-subhero-art"><img src="${art}" alt="${art.endsWith('.webp') ? 'Visuel illustratif du domaine ' + eyebrow : ''}" loading="lazy"></div></section>`;

fs.rmSync(out,{recursive:true,force:true}); fs.mkdirSync(out,{recursive:true});
fs.cpSync(path.join(root,'assets'),path.join(out,'assets'),{recursive:true});
const editorialSources=fs.readdirSync(path.join(root,'assets')).filter(name=>name.endsWith('.png'));
const imageSavings=await Promise.all(editorialSources.map(async name=>{
 const source=path.join(root,'assets',name);
 const target=path.join(out,'assets',name.replace(/\.png$/,'.webp'));
 await sharp(source).rotate().resize({width:1600,withoutEnlargement:true}).webp({quality:78,effort:5}).toFile(target);
 await sharp(source).rotate().resize({width:640,withoutEnlargement:true}).webp({quality:78}).toFile(target.replace('.webp','-640.webp'));
 return {original:fs.statSync(source).size,optimized:fs.statSync(target).size};
}));
const bytes=imageSavings.reduce((a,x)=>a+x.original,0),webpBytes=imageSavings.reduce((a,x)=>a+x.optimized,0);
console.log('Optimized '+imageSavings.length+' image assets: '+(bytes/1e6).toFixed(1)+' MB source → '+(webpBytes/1e6).toFixed(1)+' MB WebP');

