fs.copyFileSync(path.join(root,'src/editorial.css'),path.join(out,'assets/editorial.css'));
fs.copyFileSync(path.join(root,'src/reference-redesign.css'),path.join(out,'assets/reference-redesign.css'));
fs.copyFileSync(path.join(root,'src/final-design.css'),path.join(out,'assets/final-design.css'));
fs.copyFileSync(path.join(root,'src/wave1-polish.css'),path.join(out,'assets/wave1-polish.css'));
