for(const x of demos){const base='../../';write(`demonstrations/${x.id}/`,{title:`Démo interactive : ${x.title}`,description:x.short,section:'Démonstrations',body:`${hero('Démonstration · '+x.industry,x.title,x.short,`../../assets/${x.visual}`)}<section class="section demo-intro"><div><span class="eyebrow">Le scénario</span><h2>À vous de faire<br><i>avancer le dossier.</i></h2></div><p>${x.prompt} Ajoutez un nouveau dossier, faites-le passer d’une étape à l’autre et observez ce que voit l’équipe.</p></section><section class="demo-app" data-demo="${x.id}" data-steps="${esc(JSON.stringify(x.steps))}"><div class="demo-top"><div><span class="eyebrow">APERÇU INTERACTIF / ${x.industry.toUpperCase()}</span><h2>Espace de suivi</h2></div><div class="demo-actions"><button type="button" class="demo-reset">Réinitialiser</button><button type="button" class="demo-add">${x.action} +</button></div></div><div class="demo-workspace"><aside><div class="demo-side-logo"><img src="${base}assets/mark.svg" alt="" width="25" height="25"> Deux Rives Web <small>LAB</small></div><span class="demo-side-label">ESPACE DE TRAVAIL</span><b>Vue d’ensemble</b><span>Dossiers actifs</span><span>À vérifier</span><div class="demo-side-bottom">Illustration fonctionnelle<br>sans données réelles</div></aside><div class="demo-main"><div class="demo-overview"><div><span>Dossiers suivis</span><strong class="demo-count">03</strong></div><div><span>Action à prévoir</span><strong class="demo-pending">01</strong></div><div><span>Parcours</span><strong>04 étapes</strong></div></div><div class="demo-list-head"><h3>Suivi des demandes</h3><span>Cliquer sur « Étape suivante » pour faire avancer un dossier.</span></div><div class="demo-list" aria-live="polite"></div></div></div><div class="demo-foot"><span class="pulse"></span>Données fictives · état local dans ce navigateur · aucun envoi</div></section><section class="section demo-explain">${sectionHead('02','Ce que cela illustre','Un état clair pour chaque personne.')}<div class="steps-grid">${x.steps.map((p,i)=>`<div class="step"><span>0${i+1}</span><h3>${p}</h3></div>`).join('')}</div><p>Dans une version adaptée à votre organisation, les accès, les intégrations, les notifications et les règles de validation seraient définis avec votre équipe.</p></section>${cta(base)}`});}

write('realisations/',{title:'Réalisations clients et prototypes',description:'Explorez les projets clients, les prototypes et les études de conception présentés par Deux Rives Web, avec les contributions et les liens vers les démonstrations.',section:'Réalisations',body:`${hero('Réalisations','Montrer le travail.<br><i>Expliquer le contexte.</i>','Retrouvez les projets présentés par Deux Rives Web, les prototypes et les études de conception de l’agence, ainsi que des démonstrations à essayer.','../assets/sector-commerce.svg')}${portfolio.catalogue()}${portfolio.clientPreviews('../')}<section class="section">${sectionHead('01','Travaux visibles','Des parcours que vous pouvez essayer.')}<div class="demo-grid">${demos.slice(0,3).map(x=>demoCard(x,'../')).join('')}</div></section><section class="section editorial"><div class="editorial-label">Notre engagement</div><div><h2>Une preuve<br><i>sans ambiguïté.</i></h2><p>Nous distinguons les démonstrations conçues pour explorer une idée des projets réalisés pour des clients. Dès qu’une collaboration peut être publiée, son étude de cas précisera le problème, notre contribution et les résultats réellement observés.</p></div></section><section class="w4-section sage"><span class="w4-eyebrow">NIVEAUX DE PREUVE</span><h2>Le studio n’est pas une liste de clients : nous expliquons ce qui est réellement disponible.</h2><div class="w4-cards"><article><small>01 / EXPLORATION</small><h3>Concepts sectoriels</h3><p>Vingt-quatre idées de logiciels métier, chacune avec ses besoins, contraintes et scénarios fictifs. Elles montrent notre réflexion, pas une commande signée.</p></article><article><small>02 / DÉMONSTRATIONS</small><h3>Workflows testables</h3><p>Des interfaces interactives permettent de créer, modifier, faire progresser et réinitialiser des données fictives. Elles ne prouvent pas une exploitation en production.</p></article><article><small>03 / RÉALISATIONS CLIENTS</small><h3>Le contexte de chaque contribution</h3><p>Le catalogue précise l’auteur de la contribution et le type de projet. Les références commandées à Deux Rives Web seront présentées après validation de leur périmètre et de leurs résultats.</p></article></div><div class="w4-inquiries"><a href="../studio/">Explorer les 24 démonstrations ↗</a><a href="../strategie-produits/">Comprendre la stratégie produits ↗</a></div></section>${cta('../')}`});
write('agence/',{title:'À propos de Deux Rives Web',description:'Deux Rives Web conçoit des logiciels et expériences numériques pensés autour du travail réel.',section:'L’agence',body:`<section class="subhero dr-subhero studio-agency-hero"><div class="subhero-copy"><span class="eyebrow">L’agence</span><h1>Deux Rives Web, studio logiciel à Paris.</h1><p>Nous concevons des outils numériques autour des opérations de votre équipe, de la première demande au suivi quotidien.</p></div></section><section class="section editorial"><div class="editorial-label">Notre conviction</div><div><h2>Le bon logiciel<br><i>se comprend en situation.</i></h2><p>Un outil ne devient utile que lorsqu’il aide à prendre une décision, à transmettre une information ou à rendre une prochaine étape évidente. C’est pourquoi nous commençons par comprendre les parcours, les exceptions et les personnes concernées.</p><p>Nous intervenons sur l’expérience visible et sur ce qui la rend fiable : données, intégrations, droits d’accès, suivi et évolution. Le résultat doit fonctionner pour l’entreprise qui le commande et pour les personnes qui s’en servent.</p></div></section><section class="section">${sectionHead('01','Nos principes','Quatre exigences dans chaque projet.')}<div class="steps-grid">${[['Clarté','Des états et des actions compréhensibles.'],['Continuité','Un parcours complet, au-delà du premier écran.'],['Responsabilité','Des décisions humaines là où elles comptent.'],['Évolution','Un système documenté qui peut grandir.']].map((x,i)=>`<div class="step reveal"><span>0${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div></section><section class="section related"><span class="eyebrow">Nous rencontrer</span><h2>Une petite équipe, une conversation directe.</h2><p>Parlons de votre activité et de la manière dont vos outils pourraient mieux accompagner vos équipes.</p><a class="button button-outline" href="../contact/">Présenter votre besoin ${arrow}</a></section>${cta('../')}`});
write('methode/',{title:'Notre méthode de conception et développement',description:'De la découverte à la maintenance, découvrez la méthode de Deux Rives Web pour cadrer, construire et faire évoluer un logiciel.',section:'L’agence',body:`${hero('Notre méthode','De la première question<br><i>au système qui dure.</i>','Une méthode visible, des décisions expliquées et des étapes qui produisent quelque chose de vérifiable.','../assets/equipe-conception-logiciel-paris.webp')}<section class="section method-list">${[['01','Comprendre avant de dessiner','Nous échangeons avec les personnes concernées, observons les outils existants et repérons les informations, décisions et exceptions qui comptent. Le résultat est un parcours partagé, pas une longue liste de fonctions supposées.'],['02','Définir un premier périmètre utile','Nous choisissons ce que la première version doit permettre de faire, les contraintes à respecter et les critères qui montreront qu’elle fonctionne. La proposition précise livrables, étapes et responsabilités.'],['03','Concevoir et tester le parcours','Nous rendons les écrans et les transitions concrets avec un prototype. Les retours portent sur des situations réelles : que fait une personne lorsque le dossier est incomplet ou qu’un client change sa demande ?'],['04','Développer et vérifier','Nous construisons l’interface et les services nécessaires, puis testons les parcours principaux, les erreurs et les accès. Les démonstrations régulières permettent de corriger la direction avant la livraison.'],['05','Transmettre et faire évoluer','La mise en ligne comprend documentation et prise en main. Les corrections, l’assistance et les améliorations futures sont définies selon les besoins du projet.']].map(x=>`<article class="method-row reveal"><span>${x[0]}</span><h2>${x[1]}</h2><p>${x[2]}</p></article>`).join('')}</section>${cta('../')}`});
write('regards/',{title:'Regards sur le logiciel et les opérations',description:'Articles de Deux Rives Web sur l’automatisation, les outils métier et les parcours clients qui continuent après le formulaire.',section:'L’agence',body:`${hero('Regards','Des questions utiles<br><i>avant de construire.</i>','Des points de vue pratiques sur les outils, les processus et les décisions qui les relient.','../assets/flow.svg')}<section class="section insight-grid">${insights.map((x,i)=>`<a class="insight-card reveal" href="../regards/${x.id}/"><span>0${i+1} / ${x.tag}</span><h2>${x.title}</h2><p>${x.lead}</p><b>Lire l’article ${arrow}</b></a>`).join('')}</section>${cta('../')}`});
for(const x of insights) write(`regards/${x.id}/`,{title:x.title,description:x.lead,section:'L’agence',body:`<article class="article"><a class="backlink" href="../../regards/">← Tous les regards</a><span class="eyebrow">Regards · ${x.tag}</span><h1>${x.title}</h1><p class="article-lead">${x.lead}</p><p class="article-author">Rédaction Deux Rives Web · Analyse pratique · Article éditorial</p><div class="article-art"><img src="../../assets/flow.svg" alt="Illustration abstraite d’un parcours de travail relié"></div><div class="article-body">${x.paragraphs.map(p=>`<p>${p}</p>`).join('')}</div>${x.related?`<nav class="article-related" aria-label="Pour aller plus loin"><strong>Pour approfondir</strong>${x.related.map(([label,link])=>`<a href="../../${link}">${label} ↗</a>`).join('')}</nav>`:''} </article>${cta('../../')}`});

const email=config.legal.email.trim();
